/** VaTerminalLog 的类型定义 */

export type TerminalLineKind = "cmd" | "out" | "err" | "warn" | "ok";

/** 一行终端输出；字符串行等价于 { text }（kind: out） */
export interface TerminalLine {
  text: string;
  /** 行语义着色（与 ANSI 色共存：语义色优先打底，ANSI span 覆盖） */
  kind?: TerminalLineKind;
  /** 行 id；缺省用下标，流式追加时建议宿主自带 id */
  id?: string;
}

export interface TerminalLogProps {
  /** 输出行；含 ANSI 转义序列的 text 会被自动解析着色 */
  lines: (string | TerminalLine)[];
  /** 终端窗口标题栏文案，如 "bash — pnpm test" */
  title?: string;
  /** 新行到达时自动滚到底部（用户向上翻阅时暂停，滚回底部恢复）；默认 true */
  autoScroll?: boolean;
  /** 环形上限：超过后丢弃最旧行，默认 1000 */
  maxLines?: number;
  /** 显示行号 */
  showLineNumbers?: boolean;
  /** 内容区最大高度 px；不设则随内容撑开 */
  maxHeight?: number;
}

export interface TerminalLogEvents {
  /** 行复制按钮（携带该行纯文本） */
  copy: [text: string];
}

import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch, type Ref } from "vue";

import type { TerminalLine, TerminalLogProps } from "./types";

/** VaTerminalLog 的渲染行与自动滚动逻辑（bodyEl 由组件 useTemplateRef 传入） */
export function useTerminalLog(props: TerminalLogProps, bodyEl: Ref<HTMLElement | null>) {
  /** 环形裁剪后的规范行（字符串行归一为对象） */
  const rows = computed<TerminalLine[]>(() => {
    const cap = props.maxLines ?? 1000;
    const norm = props.lines.map((l, i) =>
      typeof l === "string" ? { text: l, id: String(i) } : { id: String(i), ...l },
    );
    return norm.length > cap ? norm.slice(norm.length - cap) : norm;
  });

  /** 每行解析 ANSI（只有含 ESC 的行真正解析） */
  const spans = computed<AnsiSpan[][]>(() =>
    rows.value.map((r) => (r.text.includes("\u001b") ? parseAnsiLine(r.text) : [{ text: r.text }])),
  );

  /** 行纯文本（复制用） */
  const plainText = (i: number) => spans.value[i]!.map((s) => s.text).join("");

  /* ---------- 自动滚动：贴底时跟随，上翻暂停 ---------- */
  const stickToBottom = ref(true);

  function onScroll() {
    const el = bodyEl.value;
    if (!el) return;
    stickToBottom.value = el.scrollTop + el.clientHeight >= el.scrollHeight - 32;
  }

  function scrollToBottom() {
    const el = bodyEl.value;
    if (!el) return;
    const reduced =
      typeof window !== "undefined" &&
      (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false);
    el.scrollTo({ top: el.scrollHeight, behavior: reduced ? "auto" : "smooth" });
  }

  watch(
    () => props.lines.length,
    () => {
      if (!props.autoScroll || !stickToBottom.value) return;
      nextTick(scrollToBottom);
    },
  );

  let ro: ResizeObserver | undefined;
  onMounted(() => {
    const el = bodyEl.value;
    if (el && props.autoScroll) el.scrollTop = el.scrollHeight;
    if (typeof ResizeObserver !== "undefined" && el) {
      ro = new ResizeObserver(() => {
        if (stickToBottom.value && props.autoScroll) el.scrollTop = el.scrollHeight;
      });
      ro.observe(el);
    }
  });
  onBeforeUnmount(() => ro?.disconnect());

  return { rows, spans, plainText, onScroll };
}

/* ── 内联自 @vuagent/ui src/utils/ansi.ts（registry 单文件拷贝自包含） ── */
/**
 * ANSI 转义解析（零依赖）。
 * 覆盖终端输出的常用子集：SGR 颜色/样式（含 256 色与真彩色）、
 * 其余 CSI/OSC 序列安全剥除、\r 行内重写（进度条场景）取最终帧。
 */

interface AnsiSpan {
  text: string;
  /** 前景色 CSS 值；未设置时继承 */
  color?: string;
  /** 背景色 CSS 值 */
  bgColor?: string;
  bold?: boolean;
  dim?: boolean;
  italic?: boolean;
  underline?: boolean;
}

/** ANSI 基础 + 亮色色板（xterm 惯例，暗底终端可读） */
const PALETTE__va1: string[] = [
  "#4f5b66", "#e06c75", "#98c379", "#e5c07b", "#61afef", "#c678dd", "#56b6c2", "#abb2bf",
  "#5c6370", "#e06c75", "#98c379", "#e5c07b", "#61afef", "#c678dd", "#56b6c2", "#ffffff",
];

/** xterm 256 色：0-15 色板、16-231 6×6×6 立方、232-255 灰阶 */
function color256__va1(n: number): string {
  if (n < 16) return PALETTE__va1[n]!;
  if (n < 232) {
    const v = n - 16;
    const step = [0, 95, 135, 175, 215, 255];
    const r = step[Math.floor(v / 36) % 6]!;
    const g = step[Math.floor(v / 6) % 6]!;
    const b = step[v % 6]!;
    return `rgb(${r}, ${g}, ${b})`;
  }
  const gray = 8 + (n - 232) * 10;
  return `rgb(${gray}, ${gray}, ${gray})`;
}

/** CSI 参数串（含分号/冒号） */
const CSI_RE__va1 = /\x1b\[([0-9;:]*)([A-Za-z])/g;
/** OSC（窗口标题等）…BEL 或 ST 结尾 */
const OSC_RE__va1 = /\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)/g;

interface SgrState__va1 {
  color?: string;
  bgColor?: string;
  bold?: boolean;
  dim?: boolean;
  italic?: boolean;
  underline?: boolean;
}

/** 应用一段 SGR 参数到状态 */
function applySgr__va1(state: SgrState__va1, codes: number[]) {
  let i = 0;
  while (i < codes.length) {
    const c = codes[i]!;
    if (c === 0) {
      state.color = state.bgColor = undefined;
      state.bold = state.dim = state.italic = state.underline = undefined;
    } else if (c === 1) state.bold = true;
    else if (c === 2) state.dim = true;
    else if (c === 3) state.italic = true;
    else if (c === 4) state.underline = true;
    else if (c === 22) state.bold = state.dim = undefined;
    else if (c === 23) state.italic = undefined;
    else if (c === 24) state.underline = undefined;
    else if (c >= 30 && c <= 37) state.color = PALETTE__va1[c - 30]!;
    else if (c === 38 || c === 48) {
      // 38/48;5;n 与 38/48;2;r;g;b
      const mode = codes[i + 1];
      const target = c === 38 ? "color" : "bgColor";
      if (mode === 5 && codes[i + 2] !== undefined) {
        state[target] = color256__va1(codes[i + 2]!);
        i += 2;
      } else if (mode === 2 && codes[i + 4] !== undefined) {
        state[target] = `rgb(${codes[i + 2]}, ${codes[i + 3]}, ${codes[i + 4]})`;
        i += 4;
      }
    } else if (c === 39) state.color = undefined;
    else if (c === 49) state.bgColor = undefined;
    else if (c >= 90 && c <= 97) state.color = PALETTE__va1[c - 90 + 8]!;
    else if (c >= 100 && c <= 107) state.bgColor = PALETTE__va1[c - 100 + 8]!;
    i++;
  }
}

/** 把一段纯文本 + 当前状态落成一个 span（无样式信息时省略字段） */
function pushSpan__va1(out: AnsiSpan[], text: string, st: SgrState__va1) {
  const hasStyle = st.color || st.bgColor || st.bold || st.dim || st.italic || st.underline;
  out.push(hasStyle ? { text, ...st } : { text });
}

/**
 * 解析单行（不含换行）为 span 序列。
 * - \r 重写：取 \r 分段的最后一个非空段（进度条最终帧）
 * - 非 SGR 的 CSI（光标移动等）与 OSC 剥除
 * - 空样式相邻 span 不合并由调用方处理（渲染开销可忽略）
 */
function parseAnsiLine(line: string): AnsiSpan[] {
  const crParts = line.split("\r");
  let text = crParts[crParts.length - 1] ?? "";
  text = text.replace(OSC_RE__va1, "");

  const out: AnsiSpan[] = [];
  const state: SgrState__va1 = {};
  let plain = "";
  let idx = 0;

  CSI_RE__va1.lastIndex = 0;
  for (const m of text.matchAll(CSI_RE__va1)) {
    if (m.index > idx) plain += text.slice(idx, m.index);
    idx = m.index + m[0].length;
    if (m[2] !== "m") continue; // 只处理 SGR，其余 CSI 剥除
    if (plain) {
      pushSpan__va1(out, plain, state);
      plain = "";
    }
    const params = (m[1] ?? "").split(";").map((s) => (s === "" ? 0 : Number.parseInt(s, 10)));
    applySgr__va1(state, params.length ? params : [0]);
  }
  if (idx < text.length) plain += text.slice(idx);
  if (plain) pushSpan__va1(out, plain, state);
  return out;
}

/** 整段输出（可能多行）→ 行数组；每行独立解析 */
function parseAnsi(text: string): AnsiSpan[][] {
  return text.replace(/\r\n?/g, "\n").split("\n").map(parseAnsiLine);
}
